#include "kernel-binder-wire.hpp"
using namespace sd_identity_wire;
struct Proof{uint32_t caller,receiver,payload;};
int main(int argc,char**argv){
 try{
  require(argc==5&&getuid()==0,"Usage private Binder device serverUID clientUID payload");const unsigned server_uid=std::stoul(argv[2]),client_uid=std::stoul(argv[3]),payload=std::stoul(argv[4]);require(server_uid!=client_uid&&server_uid>=10000&&client_uid>=10000,"Distinct real app UID pair");
  int ready[2];require(pipe(ready)==0,"Server readiness pipe");pid_t server=fork();require(server>=0,"Fork real service");
  if(!server){try{close(ready[0]);ordinary(server_uid);Binder binder(argv[1]);int unused=0;require(ioctl(binder.fd,BINDER_SET_CONTEXT_MGR,&unused)==0,"Claim private actual context manager");uint32_t enter=BC_ENTER_LOOPER;std::vector<uint8_t> commands;append(commands,enter);binder.exchange(commands,false);require(write(ready[1],"R",1)==1,"Service ready");close(ready[1]);auto incoming=binder.transaction(false);require(incoming.code==0x193&&incoming.sender_euid==client_uid&&incoming.sender_pid>0&&incoming.data_size==sizeof(uint32_t),"Actual kernel-stamped sender identity");uint32_t actual;memcpy(&actual,reinterpret_cast<const void*>(incoming.data.ptr.buffer),sizeof(actual));require(actual==payload,"Actual copied transaction payload");Proof proof{incoming.sender_euid,static_cast<uint32_t>(getuid()),actual+1};binder_transaction_data response{};response.data_size=sizeof(proof);response.data.ptr.buffer=reinterpret_cast<binder_uintptr_t>(&proof);commands.clear();uint32_t free_command=BC_FREE_BUFFER;append(commands,free_command);append(commands,incoming.data.ptr.buffer);uint32_t reply=BC_REPLY;append(commands,reply);append(commands,response);binder.exchange(commands,false);dprintf(1,"BINDER_SERVICE=ready|uid=%u|kernel_caller_uid=%u|forged_uid_ignored=true\n",getuid(),incoming.sender_euid);_exit(0);}catch(const std::exception&e){dprintf(2,"BINDER_SERVICE=failed|%s\n",e.what());_exit(1);}}
  close(ready[1]);char marker=0;require(read(ready[0],&marker,1)==1&&marker=='R',"Actual service ready");close(ready[0]);pid_t client=fork();require(client>=0,"Fork real client");
  if(!client){try{ordinary(client_uid);Binder binder(argv[1]);binder_transaction_data request{};request.target.handle=0;request.code=0x193;request.sender_euid=0;request.sender_pid=1;request.data_size=sizeof(payload);request.data.ptr.buffer=reinterpret_cast<binder_uintptr_t>(&payload);std::vector<uint8_t> commands;uint32_t transact=BC_TRANSACTION;append(commands,transact);append(commands,request);binder.exchange(commands,false);auto incoming=binder.transaction(true);require(incoming.data_size==sizeof(Proof),"Actual reply shape");Proof proof;memcpy(&proof,reinterpret_cast<const void*>(incoming.data.ptr.buffer),sizeof(proof));require(proof.caller==client_uid&&proof.receiver==server_uid&&proof.payload==payload+1,"Kernel UID/data round-trip");commands.clear();uint32_t free_command=BC_FREE_BUFFER;append(commands,free_command);append(commands,incoming.data.ptr.buffer);binder.exchange(commands,false);dprintf(1,"BINDER_CLIENT=ready|uid=%u|actual_service_uid=%u|actual_kernel_caller_uid=%u|payload=%u\n",getuid(),proof.receiver,proof.caller,proof.payload);_exit(0);}catch(const std::exception&e){dprintf(2,"BINDER_CLIENT=failed|%s\n",e.what());_exit(1);}}
  int client_status,server_status;require(waitpid(client,&client_status,0)==client,"Wait exact client");require(waitpid(server,&server_status,0)==server,"Wait exact service");require(WIFEXITED(client_status)&&WEXITSTATUS(client_status)==0&&WIFEXITED(server_status)&&WEXITSTATUS(server_status)==0,"Both real UID roles succeed");std::cout<<"KERNEL_BINDER_IDENTITIES=ready|server_uid="<<server_uid<<"|client_uid="<<client_uid<<"|forged_root_sender=ignored|real_data_roundtrip=true\n";return 0;
 }catch(const std::exception&e){std::cerr<<"KERNEL_BINDER_IDENTITIES=failed|"<<e.what()<<'\n';return 1;}}
